#import <UIKit/UIKit.h>
#import <Objc/runtime.h>

int main() {
    @autoreleasepool {
        UIApplication *app = [UIApplication sharedApplication];
        UIWindow *window = [[UIApplication sharedApplication].windows firstObject];

        // Try to find and dismiss any alert dialogs
        UIViewController *rootVC = window.rootViewController;

        // Look for alert controller
        if ([rootVC isKindOfClass:[UIAlertController class]]) {
            UIAlertController *alert = (UIAlertController *)rootVC;
            for (UIAlertAction *action in alert.actions) {
                if ([action.title isEqualToString:@"Cancel"]) {
                    [alert dismissViewControllerAnimated:NO completion:nil];
                    break;
                }
            }
        }

        // Try to find alert in presented controllers
        UIViewController *presented = rootVC.presentedViewController;
        while (presented) {
            if ([presented isKindOfClass:[UIAlertController class]]) {
                UIAlertController *alert = (UIAlertController *)presented;
                for (UIAlertAction *action in alert.actions) {
                    if ([action.title isEqualToString:@"Cancel"]) {
                        // Simulate the Cancel button tap
                        [alert dismissViewControllerAnimated:NO completion:nil];
                        break;
                    }
                }
            }
            presented = presented.presentedViewController;
        }
    }
    return 0;
}
